import ast

def describe_function_source(source):
    tree = ast.parse(source)
    stmt = tree.body[0]
    result = {}
    if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):
        args_node = stmt.args
        params = list(args_node.posonlyargs) + list(args_node.args)
        annotations = {}
        for a in params:
            if a.annotation is not None:
                annotations[a.arg] = ast.unparse(a.annotation)
        if stmt.returns is not None:
            annotations['return'] = ast.unparse(stmt.returns)
        defaults = [ast.literal_eval(d) for d in args_node.defaults] if args_node.defaults else None
        result['function_name'] = stmt.name
        result['is_lambda'] = False
        result['args'] = [a.arg for a in params]
        result['defaults'] = defaults
        result['annotations'] = annotations
    elif isinstance(stmt, ast.Assign):
        name = stmt.targets[0].id
        lam = stmt.value
        if not isinstance(lam, ast.Lambda):
            raise ValueError('Expected lambda assignment')
        args_node = lam.args
        params = list(args_node.posonlyargs) + list(args_node.args)
        defaults = [ast.literal_eval(d) for d in args_node.defaults] if args_node.defaults else None
        result['function_name'] = name
        result['is_lambda'] = True
        result['args'] = [a.arg for a in params]
        result['defaults'] = defaults
        result['annotations'] = {}
    else:
        raise ValueError('Unsupported statement type')
    return result

