import ast

def extract_dict_literals(text):
    n = len(text)
    fragments = []
    i = 0
    while i < n:
        if text[i] == '{':
            depth = 0
            j = i
            found = False
            while j < n:
                if text[j] == '{':
                    depth += 1
                elif text[j] == '}':
                    depth -= 1
                    if depth == 0:
                        fragments.append(text[i:j+1])
                        i = j
                        found = True
                        break
                j += 1
            if not found:
                i = n
            else:
                i += 1
        else:
            i += 1
    results = []
    for frag in fragments:
        try:
            val = ast.literal_eval(frag)
            if isinstance(val, dict):
                results.append(val)
        except Exception:
            pass
    return results

