def most_common_csv_value(csv_text):
    lines = csv_text.splitlines()
    if not lines:
        return None
    counts = {}
    order = []
    for line in lines:
        for p in line.split(','):
            val = p.strip()
            if val not in counts:
                counts[val] = 0
                order.append(val)
            counts[val] += 1
    if not order:
        return None
    best = order[0]
    best_count = counts[best]
    for val in order[1:]:
        if counts[val] > best_count:
            best = val
            best_count = counts[val]
    return (best, best_count)

def count_delimited_words(text, delimiter):
    counts = {}
    order = {}
    idx = 0
    for row in text.splitlines():
        if delimiter == '':
            cells = [row]
        else:
            cells = row.split(delimiter)
        for cell in cells:
            if cell not in counts:
                counts[cell] = 0
                order[cell] = idx
                idx += 1
            counts[cell] += 1
    words = list(counts.keys())
    words.sort(key=lambda w: (-counts[w], order[w]))
    return [(w, counts[w]) for w in words]

