import urllib.parse

def sign_request_data(req_data, secret_key):
    if not isinstance(req_data, dict):
        raise ValueError('req_data must be a dictionary')
    canonical = json.dumps(req_data, separators=(', ', ': '), ensure_ascii=True)
    digest = hmac.new(secret_key.encode('utf-8'), canonical.encode('utf-8'), hashlib.sha256).hexdigest()
    return urllib.parse.quote_plus(digest)
